CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE TABLE public.portal_sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL, account_type text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', pending_link_until timestamptz);
GRANT ALL ON public.portal_sessions TO service_role;
ALTER TABLE public.portal_sessions ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.portal_account(p_role text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb; BEGIN IF p_role NOT IN ('student','teacher','admin') THEN RAISE EXCEPTION 'Invalid account'; END IF; EXECUTE format('SELECT to_jsonb(t)-''password_hash''-''default_password'' FROM public.%I t WHERE id=$1', CASE p_role WHEN 'student' THEN 'students' WHEN 'teacher' THEN 'teachers' ELSE 'admins' END) INTO a USING p_id; RETURN a || jsonb_build_object('role',p_role); END $$;
REVOKE ALL ON FUNCTION public.portal_account(text,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.portal_issue_session(p_role text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE token text:=encode(gen_random_bytes(32),'hex'); BEGIN INSERT INTO public.portal_sessions(token_hash,user_id,account_type) VALUES(encode(digest(token,'sha256'),'hex'),p_id,p_role); RETURN jsonb_build_object('session_token',token,'account',public.portal_account(p_role,p_id)); END $$;
REVOKE ALL ON FUNCTION public.portal_issue_session(text,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.verify_portal_login(p_email text,p_password text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE a record; allowed boolean; BEGIN IF length(p_email)>255 OR length(p_password)>100 OR length(p_password)<1 THEN RETURN jsonb_build_object('success',false); END IF; allowed:=public.consume_portal_auth_attempt('portal-login:'||lower(trim(p_email))); IF NOT allowed THEN RETURN jsonb_build_object('success',false,'message','Too many attempts. Please try again in 15 minutes.'); END IF; SELECT * INTO a FROM (SELECT id,'admin' AS role,password_hash FROM public.admins WHERE lower(trim(email))=lower(trim(p_email)) UNION ALL SELECT id,'teacher',password_hash FROM public.teachers WHERE lower(trim(email))=lower(trim(p_email)) UNION ALL SELECT id,'student',password_hash FROM public.students WHERE lower(trim(email))=lower(trim(p_email))) q LIMIT 1; IF a.id IS NULL OR a.password_hash IS NULL OR a.password_hash !~ '^\$2[aby]\$' THEN RETURN jsonb_build_object('success',false); END IF; IF crypt(p_password,replace(a.password_hash,'$2b$','$2a$'))<>replace(a.password_hash,'$2b$','$2a$') THEN RETURN jsonb_build_object('success',false); END IF; RETURN public.portal_issue_session(a.role,a.id)||jsonb_build_object('success',true); END $$;
REVOKE ALL ON FUNCTION public.verify_portal_login(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.verify_portal_login(text,text) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.portal_actor() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE token text; s public.portal_sessions; BEGIN token:=coalesce(current_setting('request.headers',true),'{}')::jsonb->>'x-portal-session'; SELECT * INTO s FROM public.portal_sessions WHERE token_hash=encode(digest(coalesce(token,''),'sha256'),'hex') AND expires_at>now(); IF s.user_id IS NULL THEN RETURN NULL; END IF; RETURN public.portal_account(s.account_type,s.user_id); END $$;
REVOKE ALL ON FUNCTION public.portal_actor() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.portal_actor() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.portal_storage_access(p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.portal_actor() IS NOT NULL AND (public.portal_actor()->>'role'='admin' OR p_path LIKE (public.portal_actor()->>'role')||'/'||(public.portal_actor()->>'id')||'/%'); $$;
REVOKE ALL ON FUNCTION public.portal_storage_access(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.portal_storage_access(text) TO anon,authenticated,service_role;
CREATE POLICY "Portal photo read" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='profile-photos' AND public.portal_storage_access(name));
CREATE POLICY "Portal photo upload" ON storage.objects FOR INSERT TO anon,authenticated WITH CHECK(bucket_id='profile-photos' AND public.portal_storage_access(name));
CREATE POLICY "Portal photo delete" ON storage.objects FOR DELETE TO anon,authenticated USING(bucket_id='profile-photos' AND public.portal_storage_access(name));